fun {motive} ctorIdx =>
  bif Nat.ble ctorIdx 0 then PULift.{u, u} (motive TriangularSolve.Direction.lower)
  else PULift.{u, u} (motive TriangularSolve.Direction.upper)

fun {n} ar T b =>
  have run :=
    TriangularSolve.forwardSubstitution ar (TriangularSolve.reverseMatrix T) (TriangularSolve.reverseVector b);
  { value := TriangularSolve.reverseVector (TriangularSolve.Execution.value run),
    calls := TriangularSolve.Execution.calls run }

fun ar x x_1 =>
  match x, x_1 with
  | acc, List.nil.{0} => acc
  | acc, List.cons.{0} (Prod.mk.{0, 0} a b) rest =>
    let p := TriangularSolve.perform ar TriangularSolve.Operation.mul a b;
    let s :=
      TriangularSolve.perform ar TriangularSolve.Operation.add (TriangularSolve.Execution.value acc)
        (TriangularSolve.Execution.value p);
    TriangularSolve.dotTail._unsafe_rec ar
      { value := TriangularSolve.Execution.value s,
        calls :=
          HAppend.hAppend.{0, 0, 0}
            (HAppend.hAppend.{0, 0, 0} (TriangularSolve.Execution.calls acc) (TriangularSolve.Execution.calls p))
            (TriangularSolve.Execution.calls s) }
      rest

fun {n} ar T b x i =>
  ite.{1} (Eq.{1} (↑i) 0) (TriangularSolve.perform ar TriangularSolve.Operation.div (b i) (T i i))
    (have terms :=
      List.map.{0, 0} (fun j => Prod.mk.{0, 0} (T i j) (x j))
        (List.filter.{0} (fun j => Decidable.decide (LT.lt.{0} j i)) (List.finRange n));
    have p := TriangularSolve.sequentialDot ar terms;
    have s := TriangularSolve.perform ar TriangularSolve.Operation.sub (b i) (TriangularSolve.Execution.value p);
    have q := TriangularSolve.perform ar TriangularSolve.Operation.div (TriangularSolve.Execution.value s) (T i i);
    { value := TriangularSolve.Execution.value q,
      calls :=
        HAppend.hAppend.{0, 0, 0}
          (HAppend.hAppend.{0, 0, 0} (TriangularSolve.Execution.calls p) (TriangularSolve.Execution.calls s))
          (TriangularSolve.Execution.calls q) })

