fun {n} ar T b state i =>
  have row := TriangularSolve.forwardRow ar T b (TriangularSolve.Execution.value state) i;
  { value := Function.update.{1, 1} (TriangularSolve.Execution.value state) i (TriangularSolve.Execution.value row),
    calls := HAppend.hAppend.{0, 0, 0} (TriangularSolve.Execution.calls state) (TriangularSolve.Execution.calls row) }

fun {n} ar T b =>
  List.foldl.{0, 0} (TriangularSolve.forwardStep ar T b) { value := fun x => 0, calls := List.nil.{0} }
    (List.finRange n)

fun ar op a b =>
  have c := { operation := op, left := a, right := b };
  { value := TriangularSolve.Call.computed c ar, calls := List.cons.{0} c List.nil.{0} }

